def mism(top,bot,d):
    W=len(top[0]); res=[]
    for r in range(len(top)):
        for j in range(W):
            b = bot[r][j+d] if 0<=j+d<len(top[0]) else None
            if b is not None and (top[r][j]==0)!=(b==0):
                res.append((r,j,top[r][j],b))
    return res
