def solve(g):
    import copy
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    nz=[any(x) for x in g]; bands=[];s=None
    for i,v in enumerate(nz):
        if v and s is None: s=i
        if not v and s is not None: bands.append((s,i)); s=None
    if s is not None: bands.append((s,H))
    assert len(bands)==2, bands
    (t0,t1),(b0,b1)=bands
    top=[g[r] for r in range(t0,t1)]; bot=[g[r] for r in range(b0,b1)]
    best=None
    for a in (-1,1):
        mm=0; pairs=[]
        for ri in range(min(len(top),len(bot))):
            for j in range(W):
                k=j+a
                if 0<=k<W:
                    pairs.append((ri,j,k))
                    if (top[ri][j]==0)!=(bot[ri][k]==0): mm+=1
        if best is None or mm<best[0]: best=(mm,a,pairs)
    mm,a,pairs=best
    assert mm>0, "identical - no marks"
    out=[r[:] for r in g]
    n=0
    for ri,j,k in pairs:
        if (top[ri][j]==0)!=(bot[ri][k]==0):
            if top[ri][j]==0: out[t0+ri][j]=1
            else: out[b0+ri][k]=1
            n+=1
    return out,mm,a,n
